  "type": "object",
  "properties": {
    "items": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "maxLength": 80,
            "description": "ID intern al resursei; păstrează-l pentru cererile următoare."
          },
          "version": {
            "type": "string",
            "maxLength": 40,
            "description": "Versiunea sursei publicate sau a informării; distinctă de ID-ul intern."
          },
