          "verified"
        ],
        "additionalProperties": false
      },
      "description": "Elementele colecției, în forma și ordinea declarate de operație."
    }
  },
  "required": [
    "items"
  ],
  "additionalProperties": false,
  "description": "Structura Gs1StandardsStatus. Exemplele sunt sintetice; permisiunile și stările reale se verifică la cerere."
}
```

